#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CardKind {
    Base,
    Conditional,
    Augment,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BaseStatId {
    Ad,
    Ap,
    Haste,
    Vitality,
    Armor,
    Mr,
    Leech,
    Fleet,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MechanicTag {
    Physical,
    Magic,
    True_,
    Dot,
    OnHit,
    Returned,
    Slow,
    Heal,
    Block,
    Ramping,
    Execute,
    Crit,
    Area,
    Wish,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Self_,
    Target,
}

/// One catalog row: a folded stat row, or a full-payload card row the stat-fold kernel deliberately projects away.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum CardRow {
    Fold(EffectKind),
    Vs(VsRow),
    Scale(ScaleRow),
    OnHit(OnHitRow),
    Trigger(TriggerRow),
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct VsRow {
    pub test: VsTest,
    pub arg: f64,
    pub v: f64,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VsTest {
    Elite,
    HigherPower,
    Slowed,
    Streak,
    ThirdParty,
    HpBelow,
    PlayerAbove,
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ScaleRow {
    pub src: ScaleSrc,
    pub per: f64,
    pub step: f64,
    pub cap: f64,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ScaleSrc {
    CampsCleared,
    Streak,
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct OnHitRow {
    pub status: StatusKind,
    pub per: f64,
    pub cap: Option<f64>,
    pub ms: f64,
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TriggerRow {
    pub on: TriggerOn,
    pub arg: f64,
    pub once: bool,
    pub action: TriggerAction,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TriggerOn {
    Kill,
    Block,
    HitTaken,
    Hit,
    HpBelow,
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum TriggerAction {
    Splash {
        radius: f64,
    },
    Fortify {
        per: f64,
        cap: f64,
    },
    Status {
        to: Side,
        status: StatusKind,
        ms: f64,
        value: Option<f64>,
    },
    Boost {
        as_: f64,
        move_: f64,
        ms: f64,
    },
    Cooldown {
        ms: f64,
    },
    Return {
        melee: bool,
        share: f64,
    },
    Heal {
        share: f64,
        ms: Option<f64>,
        ignore_lockout: bool,
    },
}
/// A faction's replacement rows/text for a card (source selections; only the factions that differ are stored).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Selection {
    pub faction: crate::FactionId,
    pub text: &'static str,
    pub rows: &'static [CardRow],
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct CardDef {
    pub id: CardId,
    pub kind: CardKind,
    pub tier: u8,
    pub base: Option<BaseStatId>,
    pub requires: Option<BaseStatId>,
    pub unique: bool,
    pub ready: bool,
    pub title: &'static str,
    pub text: &'static str,
    pub tags: &'static [MechanicTag],
    pub rows: &'static [CardRow],
    /// Faction row/text replacements; a faction not listed uses `text`/`rows`.
    pub selections: &'static [Selection],
}

impl CardDef {
    /// The rows and text this card presents to a faction (source `selections`).
    pub fn selection(&self, faction: crate::FactionId) -> (&'static str, &'static [CardRow]) {
        for s in self.selections {
            if s.faction == faction {
                return (s.text, s.rows);
            }
        }
        (self.text, self.rows)
    }
}
